config <- jsonlite::fromJSON('epidemiology_config.json')
raw <- read.csv('results/extended/synthetic_longitudinal.csv',stringsAsFactors=FALSE)
clinical <- read.csv('results/extended/synthetic_clinical.csv',stringsAsFactors=FALSE)
stopifnot(nrow(raw)==2400,nrow(clinical)==600,!anyDuplicated(clinical$id),!anyDuplicated(raw[c('id','visit')]),all(table(raw$id)==4),all(sort(unique(raw$visit))==1:4),all(clinical$complication %in% 0:1),sum(clinical$complication)==86)
stopifnot(setequal(raw$id,clinical$id),all(clinical$G %in% 0:2),all(raw$outcome_day-raw$sample_day==7))
d <- merge(raw,clinical[c('id','G','complication','ascertainment_day')],by='id',sort=FALSE)
d <- d[order(d$id,d$visit),]
stopifnot(max(abs(d$genotype-(d$G-.6)))<1e-10,all(d$postpartum==as.integer(d$visit==4)),all(d$sample_gestational_week==c(14,20,26,46)[d$visit]))
d$conception_day <- d$sample_day-c(98,140,182,322)[d$visit]
stopifnot(all(tapply(d$conception_day,d$id,function(x)length(unique(x)))==1),all(d$ascertainment_day==d$conception_day+280),all(d$sample_day[d$visit<4]<d$ascertainment_day[d$visit<4]),all(d$sample_day[d$visit==4]>d$ascertainment_day[d$visit==4]))
d$heat5 <- d$temperature_C/5; d$g_centered <- d$G-.6
d$id <- factor(d$id);d$site <- factor(d$site,levels=0:2,labels=c('Site 1','Site 2','Site 3'))
d$visit <- factor(d$visit,levels=1:4,labels=c('Week 14 sample','Week 20 sample','Week 26 sample','Six week postpartum sample'))
variables <- c('temperature_C','module','depression_z','vascular_z','anxiety_z','age','deprivation','ancestry','baseline_distress','season_sin','season_cos','G','complication')
missingness <- data.frame(variable=variables,missing=vapply(d[variables],function(x)sum(is.na(x)),integer(1)))
stopifnot(all(missingness$missing==0),all(vapply(d[variables],function(x)all(is.finite(x)),logical(1))))
invariant <- c('site','neighbourhood','G','age','deprivation','ancestry','baseline_distress','complication')
stopifnot(all(vapply(invariant,function(v)all(tapply(d[[v]],d$id,function(x)length(unique(x)))==1),logical(1))))
# Independent exposure reconstruction from the original synthetic daily weather.
weather <- read.csv(gzfile('results/synthetic_daily_weather.csv.gz'),stringsAsFactors=FALSE)
weather$day <- as.integer(as.Date(weather$date)-as.Date('2010-01-01'))
stopifnot(!anyDuplicated(weather[c('site','neighbourhood','day')]))
lookup <- split(weather,paste(weather$site,weather$neighbourhood,sep=':'))
selected <- unique(round(seq(1,nrow(d),length.out=80)))
reconstructed <- vapply(selected,function(i){s<-match(d$site[i],levels(d$site))-1; w<-lookup[[paste(s,d$neighbourhood[i],sep=':')]]; z<-w$tmax_C[match((d$sample_day[i]-7):(d$sample_day[i]-1),w$day)];stopifnot(length(z)==7,all(is.finite(z)));mean(z)},numeric(1))
stopifnot(max(abs(reconstructed-d$temperature_C[selected]))<1e-8)
write.csv(data.frame(id=d$id[selected],visit=d$visit[selected],stored=d$temperature_C[selected],reconstructed=reconstructed),file.path(out,'exposure_reconstruction.csv'),row.names=FALSE)
base <- d[as.integer(d$visit)==1,]
antenatal <- d[as.integer(d$visit)<=3,]
means <- aggregate(cbind(heat5,module,season_sin,season_cos)~id,antenatal,mean)
names(means)[-1] <- paste0('antenatal_',names(means)[-1])
preg <- merge(base[c('id','site','G','g_centered','age','deprivation','ancestry','baseline_distress','complication')],means,by='id')
stopifnot(nrow(preg)==600,!anyDuplicated(preg$id))
flow <- data.frame(Stage=c('Women imported','Repeated visits imported','Duplicate woman visit records','Incomplete analysis records','Women analysed','Visits analysed','Pregnancy complications'),N=c(600,2400,0,0,600,2400,86))
write.csv(flow,file.path(out,'preprocessing_flow.csv'),row.names=FALSE);write.csv(missingness,file.path(out,'missingness.csv'),row.names=FALSE)
write.csv(d,file.path(out,'analysis_longitudinal.csv'),row.names=FALSE);write.csv(preg,file.path(out,'analysis_pregnancy.csv'),row.names=FALSE)
saveRDS(d,file.path(out,'analysis_longitudinal.rds'));saveRDS(preg,file.path(out,'analysis_pregnancy.rds'))
write.csv(data.frame(variable=c('heat5','age','deprivation','ancestry','baseline_distress','depression_z','vascular_z','anxiety_z','module','G','complication','postpartum'),definition=c('Seven day mean synthetic Tmax divided by 5; window 14 to 8 days before outcome','Standardised age surrogate; years unavailable','Continuous standardised deprivation surrogate','Continuous synthetic ancestry score','Continuous standardised baseline distress surrogate','Continuous depression surrogate; not a diagnosis','Continuous vascular surrogate','Continuous anxiety surrogate','Prespecified continuous expression module surrogate','Fictional raw allele dosage 0 1 2; centred at 0.6 in models','Generic generated pregnancy complication; 0 absent 1 present; no onset date','One postpartum sample at six weeks; outcome one week later')),file.path(out,'data_dictionary.csv'),row.names=FALSE)
jsonlite::write_json(list(women=nrow(base),visits=nrow(d),events=sum(preg$complication),source_data_regenerated=FALSE,exposure_records_checked=length(selected),maximum_exposure_error=max(abs(reconstructed-d$temperature_C[selected])),complete_records=nrow(d)),file.path(out,'preprocessing_summary.json'),pretty=TRUE,auto_unbox=TRUE)
